create type public.user_role as enum ('creator','brand','viewer','admin');
create type public.promotion_status as enum ('DRAFT','PENDING_PAYMENT','PAID','UNDER_REVIEW','ACTIVE','COMPLETED','REJECTED');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, username text unique, display_name text, avatar_url text, bio text, role public.user_role not null default 'viewer', category text, website text, suspended boolean not null default false, created_at timestamptz not null default now());
create table public.social_links (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles(id) on delete cascade, platform text not null, url text not null);
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique);
create table public.promotions (id uuid primary key default gen_random_uuid(), creator_id uuid not null references public.profiles(id) on delete cascade, title text not null, description text not null, content_url text not null, platform text not null, category text not null, package text not null, status public.promotion_status not null default 'DRAFT', estimated_impressions integer, start_date timestamptz, end_date timestamptz, created_at timestamptz not null default now());
create table public.payments (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), promotion_id uuid not null references public.promotions(id), stripe_payment_id text unique, amount integer not null, currency text not null default 'usd', status text not null, created_at timestamptz not null default now());
create table public.promotion_events (id uuid primary key default gen_random_uuid(), promotion_id uuid not null references public.promotions(id) on delete cascade, user_id uuid references public.profiles(id), event_type text not null check (event_type in ('view','click','profile_view','like','share')), created_at timestamptz not null default now());
create table public.reports (id uuid primary key default gen_random_uuid(), reporter_id uuid references public.profiles(id), promotion_id uuid references public.promotions(id), reason text not null, description text, status text not null default 'OPEN', created_at timestamptz not null default now());
create table public.favorites (user_id uuid references public.profiles(id) on delete cascade, promotion_id uuid references public.promotions(id) on delete cascade, created_at timestamptz default now(), primary key(user_id,promotion_id));
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null, message text not null, read boolean not null default false, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.social_links enable row level security; alter table public.categories enable row level security; alter table public.promotions enable row level security; alter table public.payments enable row level security; alter table public.promotion_events enable row level security; alter table public.reports enable row level security; alter table public.favorites enable row level security; alter table public.notifications enable row level security;
create policy "public profiles are readable" on public.profiles for select using (not suspended); create policy "users edit own profile" on public.profiles for update using (auth.uid()=id) with check(auth.uid()=id); create policy "users create own profile" on public.profiles for insert with check(auth.uid()=id);
create policy "public categories are readable" on public.categories for select using (true);
create policy "public active promotions" on public.promotions for select using (status='ACTIVE' or creator_id=auth.uid()); create policy "creators create promotions" on public.promotions for insert with check(creator_id=auth.uid()); create policy "creators update drafts" on public.promotions for update using(creator_id=auth.uid() and status in ('DRAFT','PENDING_PAYMENT'));
create policy "owners see payments" on public.payments for select using(user_id=auth.uid()); create policy "users see own notifications" on public.notifications for select using(user_id=auth.uid()); create policy "users update notifications" on public.notifications for update using(user_id=auth.uid()); create policy "users manage favorites" on public.favorites for all using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "authenticated report" on public.reports for insert with check(reporter_id=auth.uid());
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$ begin insert into public.profiles (id, role) values (new.id, coalesce((new.raw_user_meta_data->>'role')::public.user_role,'viewer')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
